import java.util.*;
import java.util.function.*;

public class Ex07 {
    // 三级缓存
    static final Map<String,Object> singletonObjects = new HashMap<>();      // 一级：成品
    static final Map<String,Object> earlySingletonObjects = new HashMap<>(); // 二级：半成品（已实例化未填充）
    static final Map<String,ObjectFactory<?>> singletonFactories = new HashMap<>(); // 三级：早期引用工厂

    static class A { B b; void setB(B b){this.b=b;} }
    static class B { A a; void setA(A a){this.a=a;} }
    interface ObjectFactory<T> { T getObject(); }

    static A createA() {
        A a = new A();
        singletonFactories.put("a", () -> a); // 暴露早期引用到三级缓存
        B b = getBeanB();                      // 填充属性：需要 B
        a.setB(b);
        singletonObjects.put("a", a);
        earlySingletonObjects.remove("a");
        singletonFactories.remove("a");
        return a;
    }
    static B createB() {
        B b = new B();
        singletonFactories.put("b", () -> b);
        A a = getBeanA();
        b.setA(a);
        singletonObjects.put("b", b);
        earlySingletonObjects.remove("b");
        singletonFactories.remove("b");
        return b;
    }
    static A getBeanA() {
        if (singletonObjects.containsKey("a")) return (A) singletonObjects.get("a");
        if (earlySingletonObjects.containsKey("a")) return (A) earlySingletonObjects.get("a");
        if (singletonFactories.containsKey("a")) {
            A early = (A) singletonFactories.get("a").getObject();
            earlySingletonObjects.put("a", early); // 升级到二级缓存
            return early;
        }
        return createA();
    }
    static B getBeanB() {
        if (singletonObjects.containsKey("b")) return (B) singletonObjects.get("b");
        if (earlySingletonObjects.containsKey("b")) return (B) earlySingletonObjects.get("b");
        if (singletonFactories.containsKey("b")) {
            B early = (B) singletonFactories.get("b").getObject();
            earlySingletonObjects.put("b", early);
            return early;
        }
        return createB();
    }
    public static void main(String[] args) {
        A a = getBeanA();
        System.out.println("a.b == b ? " + (a.b != null));
        System.out.println("b.a == a ? " + (a.b.a != null));
        System.out.println("a.b.a == a ? " + (a.b.a == a));
    }
}
